% StarIntel Universe — control plane loader.
% Canonical entry: :- [universe].
%
% Layers (load order matters):
%   1. components.pl       — static component registry
%   2. dependencies.pl     — dependency graph + closure reasoning
%   3. update_policy.pl    — submodule candidate admissibility
%   4. merge_policy.pl     — required checks + merge gate
%   5. release_policy.pl   — release gate
%   6. deployment_policy.pl— stage transitions
%
% Dynamic facts (machine-generated by scripts/collect-facts.sh, never
% hand-edited, never containing secrets):
%   pin/3, check/2, upstream_head/2, artifact/3, revision_note/2
%
% This file is part of the tracked control plane. Task-scoped verification
% state lives in .prolog/facts.kb (untracked runtime state).

:- dynamic(pin/3).
:- dynamic(check/2).
:- dynamic(upstream_head/2).
:- dynamic(artifact/3).
:- dynamic(revision_note/2).

universe_version(1).

universe_control_plane_files(
    [ 'components.pl'
    , 'dependencies.pl'
    , 'update_policy.pl'
    , 'merge_policy.pl'
    , 'release_policy.pl'
    , 'deployment_policy.pl'
    ]).

load_control_plane :-
    universe_control_plane_files(Files),
    maplist(consult_from_here, Files).

consult_from_here(File) :-
    prolog_load_context(directory, Dir),
    directory_file_path(Dir, File, Path),
    consult(Path).

% facts_dir/1 resolves the machine-generated fact directory. Override with
% the STARINTEL_UNIVERSE_FACTS environment variable.
facts_dir(Dir) :-
    getenv('STARINTEL_UNIVERSE_FACTS', Env), Env \= '', !,
    Dir = Env.
facts_dir('facts').

load_facts :-
    facts_dir(Dir),
    exists_directory(Dir),
    !,
    directory_files(Dir, Entries),
    member(File, Entries),
    file_name_extension(_, pl, File),
    directory_file_path(Dir, File, Path),
    exists_file(Path),
    consult(Path),
    fail.
load_facts.

% must/1: policy helper — throws a typed policy_violation instead of
% silently failing, so CI can distinguish "policy said no" from crash.
must(Goal) :-
    (   call(Goal)
    ->  true
    ;   throw(error(policy_violation(Goal), _))
    ).

:- load_control_plane.
